# One-off migration (already applied): collapse every CollapseBox by default and add the options
# "Method notes" (showHelp) and "Data and setup guide" (showGuide) at the end of every analysis,
# like the rdfamily / scmfamily modules. The single-estimator files are generated by dev/gen_single.py,
# which now contains the same changes; this script patches the six hand-written analyses.
import os, re
os.chdir(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'))
HAND = ['didsetup', 'did22', 'didcompare', 'didiag', 'dosedid', 'dddcompare']

def rw(path, fn):
    s = open(path, encoding='utf-8').read()
    t = fn(s)
    open(path, 'w', encoding='utf-8', newline='\n').write(t)

OPTS = ("    - name: showHelp\n      title: Method notes\n      type: Bool\n      default: false\n"
        "      description:\n          R: '`TRUE` or `FALSE` (default), show notes on what the method does and how to read the results'\n\n"
        "    - name: showGuide\n      title: Data and setup guide\n      type: Bool\n      default: false\n"
        "      description:\n          R: '`TRUE` or `FALSE` (default), show a guide to the variables and the data format'\n\n")
UI = ("  - type: CollapseBox\n    label: Notes and guide\n    collapsed: true\n    stretchFactor: 1\n    children:\n"
      "      - type: LayoutBox\n        margin: large\n        children:\n"
      "          - type: CheckBox\n            name: showHelp\n"
      "          - type: CheckBox\n            name: showGuide\n")

for n in HAND:
    rw(f'jamovi/{n}.a.yaml', lambda s: re.sub(r'\n\.\.\.\s*$', '\n', s.rstrip() ).rstrip('\n') + '\n\n' + OPTS + '...\n')
    rw(f'jamovi/{n}.u.yaml', lambda s: s.replace('collapsed: false', 'collapsed: true').rstrip('\n') + '\n' + UI)
    def r(s):
        s = re.sub(r'(    - name: notes\n      title: [^\n]*\n      type: Html\n)', r'\1      visible: (showHelp)\n', s)
        guide = "    - name: guide\n      title: Data and setup guide\n      type: Html\n      visible: (showGuide)\n\n"
        s = re.sub(r'\n\.\.\.\s*$', '', s.rstrip()) + '\n\n' + guide + '...\n'
        return s
    rw(f'jamovi/{n}.r.yaml', r)

# the empty-state message of the panel check was written to `notes`: give it its own item
def setup_r(s):
    return s.replace("items:\n", "items:\n    - name: info\n      title: Panel check\n      type: Html\n\n", 1)
rw('jamovi/didsetup.r.yaml', setup_r)
rw('R/didsetup.b.R', lambda s: s.replace("self$results$notes$setContent(paste0(\n                    \"<p>Select a unit ID", "self$results$info$setContent(paste0(\n                    \"<p>Select a unit ID", 1))

# guide content at the start of every .run
for n in HAND:
    rw(f'R/{n}.b.R', lambda s: s.replace("        .run = function() {\n", f"        .run = function() {{\n            self$results$guide$setContent(dc_guide_html(\"{n}\"))\n", 1))
print('ok')
